    return {
      id: r.i,
      title: r.t,
      slug: r.sl,
      genre: at(genres, r.g),
      subgenres: (r.sg || []).map((i) => subgenres[i]),
      company: r.c ?? null,
      duration: r.d ?? null,
      ageRestriction: at(ageRestrictions, r.ar),
      free: r.f === 1,
      image,
      // smallImage is dropped when identical to image; the client mirrors it.
      smallImage: "si" in r ? imageUrl(r.si) : image,
      blurb: r.b ?? "",
      venue: r.v ?? null,
      venueName,
      room,
