19	  why:
20	    'the wire format ships the lookup lists once and references them by position, so an index the list no longer has (or a list regenerated without its day files) mislabels shows silently — the client renders undefined, or worse, the neighbouring genre',
21	  doc: 'scraper/README.md',
22	
23	  run(ctx) {
24	    const raw = ctx.read(LOOKUPS);
25	    if (raw === null) return []; // relevance-first: no data layer in this repo state
26	
27	    let lookups;
28	    try {
29	      lookups = JSON.parse(raw);
30	    } catch (e) {
31	      return [finding(LOOKUPS, `data/venues.json is not valid JSON: ${e.message}`,
