41	    // (normalize.py writes -1; adaptShow resolves it to no room / no status).
42	    const dayFields = [
43	      ['genre', 'genres', false],
44	      ['room', 'rooms', true],
45	      ['ts', 'ticketStatuses', true],
46	    ];
47	    // shows.min.json's shorter keys, same lists. No ticket status here: it moved
48	    // to availability.min.json so the catalogue could stop changing hourly (#249),
49	    // and it is checked separately below against that file's own status list.
50	    const masterFields = [
51	      ['g', 'genres', false],
52	      ['rm', 'rooms', true],
53	      ['ar', 'ageRestrictions', true],
54	    ];
55	
56	    function finding(file, what, fix) {
57	      return {
58	        rule: rule.id,
59	        severity: rule.severity,
60	        file,
61	        line: null,
62	        what,
63	        why: rule.why,
64	        fix,
