+  const saved = globalThis.fetch;
+  globalThis.fetch = async () => ({ ok: false, status: 404, json: async () => ({}) });
+  try {
+    await assert.rejects(() => fetchJson("data/venues.json"), /HTTP 404 fetching data\/venues\.json/);
+  } finally {
+    globalThis.fetch = saved;
+  }
+});

