import json, subprocess

def show(ref, path):
    r = subprocess.run(['git','show',f'{ref}:{path}'],capture_output=True,text=True)
    return json.loads(r.stdout)

MASTER='data/normalized/shows.json'
main   = show('origin/main', MASTER)            # newest catalogue content (daily top-up)
ours   = show('HEAD', MASTER)                   # our refreshed statuses
base   = show(subprocess.run(['git','merge-base','HEAD','origin/main'],capture_output=True,text=True).stdout.strip(), MASTER)

# Our side's contribution is exactly the per-performance status/soldOut refresh.
# Take main's records as the trunk (it has shows ours never saw) and overlay our
# statuses onto them, keyed by show id + date + start.
ours_status = {}
for s in ours:
    for p in s.get('performances') or []:
        ours_status[(s['id'], p['date'], p['start'])] = (p.get('status'), p.get('soldOut'))

base_status = {}
for s in base:
    for p in s.get('performances') or []:
        base_status[(s['id'], p['date'], p['start'])] = (p.get('status'), p.get('soldOut'))

applied = skipped = 0
for s in main:
    for p in s.get('performances') or []:
        k = (s['id'], p['date'], p['start'])
        if k not in ours_status:
            continue
        st, so = ours_status[k]
        if base_status.get(k) == (st, so):
            continue                       # our side didn't change it; nothing to carry
        cur = (p.get('status'), p.get('soldOut'))
        if cur != base_status.get(k):
            skipped += 1                   # main moved it too — leave main's value
            continue
        p['status'], p['soldOut'] = st, so
        applied += 1

print(f'carried {applied} refreshed statuses onto main\'s master; '
      f'{skipped} left to main (it moved them too)')
print(f'shows: base {len(base)}, ours {len(ours)}, main {len(main)} -> merged {len(main)}')
with open(MASTER,'w') as f:
    json.dump(main, f, ensure_ascii=False, separators=(',',':'))
